dirLight.position.set(5, 5, 5);
scene.add(dirLight);

camera.position.z = 4;
renderer.render(scene, camera);

import * as THREE from 'three';

const vertexShader = `
  varying vec2 vUv;
  void main() {
    vUv = uv;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;

const fragmentShader = `
  varying vec2 vUv;
  uniform vec3 colorA;
  uniform vec3 colorB;
  void main() {
    vec3 col = mix(colorA, colorB, vUv.y);
    gl_FragColor = vec4(col, 1.0);
  }
`;

const material = new THREE.ShaderMaterial({
  vertexShader,
  fragmentShader,
  uniforms: {
    colorA: { value: new THREE.Color(0xff0000) },
    colorB: { value: new THREE.Color(0x0000ff) }
  }
});

const mesh = new THREE.Mesh(new THREE.PlaneGeometry(2, 2), material);

import * as THREE from 'three';

const vertexShader = `
  uniform float uTime;
  varying vec2 vUv;
  void main() {
    vUv = uv;
    vec3 pos = position;
    pos.z += sin(pos.x * 5.0 + uTime) * 0.2;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
  }
`;

const fragmentShader = `
  varying vec2 vUv;
  void main() {
    gl_FragColor = vec4(vUv.x, vUv.y, 1.0, 1.0);
  }
`;

const material = new THREE.ShaderMaterial({
  vertexShader,
  fragmentShader,
  uniforms: {
    uTime: { value: 0 }
  },
  wireframe: true
});

const plane = new THREE.Mesh(new THREE.PlaneGeometry(4, 4, 32, 32), material);
